from pathlib import Path
import base64,re,sys,xml.etree.ElementTree as ET
root=Path(sys.argv[1])
HERE=Path(__file__).resolve().parent
logo=base64.b64decode('')
ico=base64.b64decode('')
(root/'images/incrovax.png').write_bytes(logo)
(root/'src/MeshServer.ico').write_bytes(ico)
# Preserve namespaces, service protocol and upstream authorship. Change display resources only.
for path in root.rglob('*.resx'):
 tree=ET.parse(path);changed=False
 for data in tree.getroot().findall('data'):
  value=data.find('value')
  if value is None:continue
  if data.get('name')=='MeshCentral' and path.parent.name=='Properties':
   data.attrib.clear();data.set('name','MeshCentral');data.set('type','System.Resources.ResXFileRef, System.Windows.Forms')
   value.text=r'..\images\incrovax.png;System.Drawing.Bitmap, System.Drawing';changed=True
  elif 'System.Drawing.Icon' in data.get('type','') and data.get('mimetype')=='application/x-microsoft.net.object.bytearray.base64':
   value.text=base64.b64encode(ico).decode();changed=True
  elif not data.get('mimetype') and not data.get('type') and value.text and not re.search('copyright|apache|license|lizenz',value.text,re.I):
   text=re.sub(r'MeshCentral[ -]?(?:Assistant|Assistent)', 'INCrovax Support Assistant',value.text,flags=re.I)
   text=re.sub(r'Mesh[ -]?Agent','INCrovax Support Agent',text,flags=re.I)
   if text!=value.text:value.text=text;changed=True
 if changed:tree.write(path,encoding='utf-8',xml_declaration=True)
for path in (root/'src').glob('*.cs'):
 if path.name.endswith('.Designer.cs'):continue
 content=path.read_text(encoding='utf-8-sig')
 if 'InitializeComponent();' in content:
  content=content.replace('InitializeComponent();','InitializeComponent();\n            IncrovaxTheme.Apply(this);')
 if path.name=='MainForm.cs':
  content=content.replace('IncrovaxTheme.Apply(this);','IncrovaxTheme.Apply(this);\n            mainNotifyIcon.Icon = this.Icon;')
  old='if (msh == null) { msh = MeshCentralAgent.LoadMshFileStr(); }'
  assert old in content
  content=content.replace(old,old+'\n            if (msh == null) { msh = "AutoConnect=4\\r\\nTitle=INCrovax Support Assistant\\r\\ndisableUpdate=1\\r\\n"; }')
 if path.name=='Translate.cs':
  content=content.replace('return english;', 'return IncrovaxTheme.Brand(english);').replace('return translations[lang];','return IncrovaxTheme.Brand(translations[lang]);')
 path.write_text(content,encoding='utf-8-sig')
assembly=root/'Properties/AssemblyInfo.cs';text=assembly.read_text(encoding='utf-8-sig')
for key,value in [('AssemblyTitle','INCrovax Support Assistant'),('AssemblyDescription','INCrovax Support Assistant – angepasster Monitor für den vorhandenen Fernwartungsdienst'),('AssemblyCompany','INCrovax e.K.'),('AssemblyProduct','INCrovax Fernwartung')]:
 text=re.sub(r'\[assembly: '+key+r'\(".*?"\)\]',lambda m:'[assembly: '+key+'("'+value+'")]',text)
text=re.sub(r'AssemblyVersion\("[^"]+"\)','AssemblyVersion("4.0.0.0")',text);text=re.sub(r'AssemblyFileVersion\("[^"]+"\)','AssemblyFileVersion("4.0.0.0")',text)
assembly.write_text(text,encoding='utf-8-sig')
project=root/'MeshCentralAssistant.csproj';text=project.read_text(encoding='utf-8-sig').replace('<AssemblyName>MeshCentralAssistant</AssemblyName>','<AssemblyName>INCrovax-Support-Assistant</AssemblyName>')
text=text.replace('<Compile Include="src\\Program.cs" />','<Compile Include="src\\Program.cs" />\n    <Compile Include="src\\IncrovaxTheme.cs" />')
project.write_text(text,encoding='utf-8-sig')
(root/'src/IncrovaxTheme.cs').write_text('''using System;
using System.Drawing;
using System.Text.RegularExpressions;
using System.Windows.Forms;
namespace MeshAssistant {
 internal static class IncrovaxTheme {
  internal static readonly Color Background=Color.FromArgb(16,18,20), Panel=Color.FromArgb(26,30,36), Text=Color.FromArgb(228,233,239), Green=Color.FromArgb(107,237,0);
  internal static string Brand(string s) {
   if(s==null || Regex.IsMatch(s,"copyright|apache|license|lizenz",RegexOptions.IgnoreCase)) return s;
   s=Regex.Replace(s,@"MeshCentral[ -]?(Assistant|Assistent)","INCrovax Support Assistant",RegexOptions.IgnoreCase);
   return Regex.Replace(s,@"Mesh[ -]?Agent","INCrovax Support Agent",RegexOptions.IgnoreCase);
  }
  internal static void Apply(Form form) {
   Walk(form);
   foreach(var field in form.GetType().GetFields(System.Reflection.BindingFlags.Instance|System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Public)) {
    var menu=field.GetValue(form) as ContextMenuStrip;
    if(menu!=null) Walk(menu);
    var notify=field.GetValue(form) as NotifyIcon;
    if(notify!=null) {notify.Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);notify.Text="INCrovax Support Assistant";}
   }
   form.BackColor=Background;form.ForeColor=Text;
   form.Icon=Icon.ExtractAssociatedIcon(Application.ExecutablePath);
  }
  private static void Walk(Control control) {
   control.Text=Brand(control.Text);
   if(!(control is PictureBox)) {control.BackColor=Panel;control.ForeColor=Text;}
   var button=control as Button;
   if(button!=null) {
    button.UseVisualStyleBackColor=false;button.FlatStyle=FlatStyle.Flat;
    button.FlatAppearance.BorderColor=Green;button.FlatAppearance.MouseOverBackColor=Color.FromArgb(41,51,34);
    button.BackColor=Color.FromArgb(37,46,56);button.ForeColor=Text;
   }
   var menu=control as ToolStrip;
   if(menu!=null) {menu.BackColor=Panel;menu.ForeColor=Text;menu.Renderer=new ToolStripProfessionalRenderer(new Palette());foreach(ToolStripItem item in menu.Items){item.Text=Brand(item.Text);item.ForeColor=Text;}}
   foreach(Control child in control.Controls) Walk(child);
  }
  private class Palette:ProfessionalColorTable {
   public override Color ToolStripDropDownBackground {get{return Panel;}}
   public override Color ImageMarginGradientBegin {get{return Panel;}}
   public override Color ImageMarginGradientMiddle {get{return Panel;}}
   public override Color ImageMarginGradientEnd {get{return Panel;}}
   public override Color MenuItemSelected {get{return Color.FromArgb(41,51,34);}}
   public override Color MenuItemBorder {get{return Green;}}
  }
 }
}''',encoding='utf-8')
print('Assistant CI patch applied; no service/protocol/certificate/consent implementation changed.')
